mapper.select:
SELECT

FROM videos
WHERE user_id = #{userId}
AND deleted = 0
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO videos (
user_id, status, storage_info, metadata, location, error_message,
created_at, updated_at, deleted
) VALUES (
#{userId}, #{status}, #{storageInfo}, #{metadata}, #{location}, #{errorMessage},
#{createdAt}, #{updatedAt}, #{deleted}
)

mapper.update:
UPDATE videos
status = #{status}, storage_info = #{storageInfo}, metadata = #{metadata}, location = #{location}, error_message = #{errorMessage}, updated_at = #{updatedAt}
WHERE id = #{id} AND deleted = 0
